async function cancelled(p: Promise<unknown>, message: string): Promise<void> {
  const err = await p.then(
    () => undefined,
    (e: unknown) => e,
  );
  expect(err).toBeInstanceOf(CancelledError);
  expect((err as CancelledError).code).toBe("CANCELLED");
  expect((err as CancelledError).retryable).toBe(false);
  expect((err as CancelledError).message).toBe(message);
}

describe("closed secrets provider (SPEC 2.4)", () => {
  it("every operation after close() fails with CANCELLED before reaching the service", async () => {
    const p = new InMemorySecretsProvider({ initial: { a: "1" } });
    expect(p.closed).toBe(false);
    expect(await p.getString("a")).toBe("1");
    await p.close();
    await p.close();
    expect(p.closed).toBe(true);
    const before = { ...p.calls };
    await cancelled(p.get("a"), "secrets.get a: client is closed");
    await cancelled(p.getString("a"), "secrets.get a: client is closed");
    await cancelled(p.require("a"), "secrets.get a: client is closed");
    await cancelled(p.getMany(["a"]), "secrets.get a: client is closed");
    await cancelled(p.list(), "secrets.list: client is closed");
    await cancelled(p.getAll(), "secrets.list: client is closed");
    await cancelled(p.set("a", "2"), "secrets.set a: client is closed");
    await cancelled(p.delete("a"), "secrets.delete a: client is closed");
    await cancelled(p.metadata("a"), "secrets.metadata a: client is closed");
    await cancelled(p.loadEnv({ A: "a" }, { env: {} }), "secrets.get a: client is closed");
    expect(() => p.watch("a", 1000, () => undefined)).toThrow(CancelledError);
    expect(p.calls).toEqual(before);
  });

  it("close() stops watchers first and SecretCache follows the same rule", async () => {
    const p = new InMemorySecretsProvider({ initial: { a: "1" } });
    const w = p.watch("a", 1000, () => undefined);
    await w.ready;
    await p.close();
    expect(w.stopped).toBe(true);

    const inner = new InMemorySecretsProvider({ initial: { a: "1" } });
    const cache = new SecretCache(inner);
    expect(await cache.getString("a")).toBe("1");
    await cache.close();
    await cancelled(cache.get("a"), "secrets.get a: client is closed");
    expect(inner.closed).toBe(false);
    expect(await inner.getString("a")).toBe("1");
  });
});
